let editorAirports={},editorNames={},editorReady=false,editingId=null,recordPage=0,lastDataset=null,undoDeletion=null,editorSaving=false;
const pageSize=12;
const rowId=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'row-'+Date.now()+'-'+Math.random().toString(36).slice(2);
function ensureRowIds(){for(const row of state.rows||[])if(!row._id)row._id=rowId();}
function recordCanceled(row){return ['true','1','是','yes','已取消'].includes(String(row.canceled).trim().toLowerCase());}
function recordAirportName(code){const c=airportCode(code),a=editorAirports[c];return editorNames[c]||a?.city||a?.name||c||'未填写';}
function airportDescription(code){const c=airportCode(code),a=editorAirports[c];return a?`${recordAirportName(c)} · ${a.name} · ${c}`:'';}
function recordIdentity(row){return [dateValue(row.date),normalizeAirlineCode(row.airline),String(row.flight||'').trim(),airportCode(row.from),airportCode(row.to)].join('|');}
function recordStatuses(){const result=new Map(),cutoff=$('cutoff').value;for(const row of state.rows||[]){let key='included';if(!dateValue(row.date)||!validAirlineCode(normalizeAirlineCode(row.airline))||!editorAirports[airportCode(row.from)]||!editorAirports[airportCode(row.to)])key='invalid';else if(recordCanceled(row))key='canceled';else if(dateValue(row.date)>cutoff)key='future';result.set(row._id,key);}return result;}
function recordFeedback(message,undo=false){$('record-feedback').replaceChildren(document.createTextNode(message));if(undo){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent='撤销删除';button.addEventListener('click',async()=>{if(!undoDeletion||undoDeletion.dataset!==state.rows)return;state.rows.splice(undoDeletion.index,0,undoDeletion.row);undoDeletion=null;await regenerate();recordFeedback('已恢复这条航班记录。');});$('record-feedback').append(button);}}
function aircraftKey(row){return String(row.aircraft||'').trim()||'__unknown__';}
function updateRecordFilterOptions(rows){for(const [id,values,label] of [['record-year',[...new Set(rows.map(r=>dateValue(r.date)?.slice(0,4)).filter(Boolean))].sort().reverse(),'全部年份'],['record-aircraft',[...new Set(rows.map(aircraftKey))].sort((a,b)=>a.localeCompare(b)),'全部机型']]){const select=$(id),value=select.value;select.replaceChildren(new Option(label,'all'),...values.map(v=>new Option(v==='__unknown__'?'未填写机型':v,v)));select.value=values.includes(value)?value:'all';}}
function renderRecordPages(pages){const box=$('record-pages');box.replaceChildren();const indices=[...new Set([0,recordPage-1,recordPage,recordPage+1,pages-1])].filter(i=>i>=0&&i<pages).sort((a,b)=>a-b);for(const [n,i] of indices.entries()){if(n&&i-indices[n-1]>1){const gap=document.createElement('span');gap.textContent='…';box.append(gap);}const button=document.createElement('button');button.type='button';button.className='pager';button.textContent=String(i+1);button.setAttribute('aria-label',`第 ${i+1} 页`);if(i===recordPage)button.setAttribute('aria-current','page');button.addEventListener('click',()=>{recordPage=i;renderRecords();});box.append(button);}}
function renderRecords(){ensureRowIds();if(lastDataset!==state.rows){recordPage=0;lastDataset=state.rows;undoDeletion=null;$('record-feedback').replaceChildren();}const rows=state.rows||[],statuses=recordStatuses(),query=$('record-search').value.trim().toLowerCase(),filter=$('record-filter').value;
 updateRecordFilterOptions(rows);const year=$('record-year').value,aircraft=$('record-aircraft').value;
 const selected=rows.filter(row=>{const text=[row.from,row.to,row.airline,row.flight,recordAirportName(row.from),recordAirportName(row.to),editorAirports[airportCode(row.from)]?.name,editorAirports[airportCode(row.to)]?.name].join(' ').toLowerCase();return (!query||text.includes(query))&&(filter==='all'||statuses.get(row._id)===filter)&&(year==='all'||dateValue(row.date)?.slice(0,4)===year)&&(aircraft==='all'||aircraftKey(row)===aircraft);}).sort((a,b)=>(dateValue(b.date)||'').localeCompare(dateValue(a.date)||''));
 const pages=Math.max(1,Math.ceil(selected.length/pageSize));recordPage=Math.min(recordPage,pages-1);const page=selected.slice(recordPage*pageSize,(recordPage+1)*pageSize);
 $('records-count').textContent=rows.length?`${rows.length} 条记录 · 修改后地图与统计自动更新`:'导入记录后可逐条修改，也可以从第一班开始手动添加。';$('export-records').disabled=!rows.length;$('record-table-wrap').hidden=!page.length;$('records-empty').hidden=!!page.length;$('records-empty').textContent=rows.length?'没有匹配的记录，试试调整搜索或筛选。':'航班记录会显示在这里。你也可以直接手动添加，无需上传文件。';$('record-body').replaceChildren();
 const statusText={included:'历史行程',future:'未来行程',canceled:'已取消',duplicate:'重复记录',invalid:'需修正'};
 for(const row of page){const tr=document.createElement('tr');tr.dataset.recordId=row._id;const date=document.createElement('td');date.textContent=dateValue(row.date)||String(row.date||'未填写');date.className='record-date';const route=document.createElement('td');const main=document.createElement('strong');main.className='record-route-main';main.textContent=`${recordAirportName(row.from)} → ${recordAirportName(row.to)}`;const sub=document.createElement('span');sub.className='record-route-sub';sub.textContent=`${airportCode(row.from)||'—'} → ${airportCode(row.to)||'—'}`;route.append(main,sub);const flight=document.createElement('td');flight.textContent=[row.airline,row.flight].filter(Boolean).join(' ')||'未填写';const badgeCell=document.createElement('td');const badge=document.createElement('span');badge.className='record-status '+statuses.get(row._id);badge.textContent=statusText[statuses.get(row._id)];badgeCell.append(badge);const actions=document.createElement('td');actions.className='record-row-actions';const edit=document.createElement('button');edit.type='button';edit.className='record-action';edit.textContent='编辑';edit.setAttribute('aria-label',`编辑 ${date.textContent} ${sub.textContent}`);edit.addEventListener('click',()=>openFlightDialog(row._id));const remove=document.createElement('button');remove.type='button';remove.className='record-action remove';remove.textContent='删除';remove.setAttribute('aria-label',`删除 ${date.textContent} ${sub.textContent}`);remove.addEventListener('click',async()=>{const index=state.rows.findIndex(x=>x._id===row._id);if(index<0)return;undoDeletion={dataset:state.rows,index,row:state.rows[index]};state.rows.splice(index,1);await regenerate();recordFeedback('已删除一条记录。',true);});actions.append(edit,remove);const aircraftCell=document.createElement('td');aircraftCell.className='record-aircraft';const aircraftName=String(row.aircraft||'').trim();const aircraftLabel=document.createElement('span');aircraftLabel.textContent=aircraftName||'未填写';const aircraftWrap=document.createElement('div');aircraftWrap.className='record-aircraft-content';if(aircraftName&&typeof ribbonEntry==='function'){const entry=ribbonEntry(aircraftName);if(entry){const image=document.createElement('img');image.className='record-aircraft-badge';image.src='assets/aircraft-ribbon/'+entry[0]+'.webp';image.alt='';image.loading='lazy';image.decoding='async';image.width=48;image.height=48;image.addEventListener('error',()=>image.remove(),{once:true});aircraftWrap.append(image);}}aircraftWrap.append(aircraftLabel);aircraftCell.append(aircraftWrap);tr.append(date,route,flight,aircraftCell,badgeCell,actions);$('record-body').append(tr);}
 $('record-page-info').textContent=selected.length?`${recordPage*pageSize+1}–${Math.min((recordPage+1)*pageSize,selected.length)} / ${selected.length} 条`:'';$('record-prev').disabled=recordPage===0;$('record-next').disabled=recordPage>=pages-1;renderRecordPages(pages);
}
function updateAirportSelection(which){const input=$('flight-'+which),code=airportCode(input.value),node=$(which+'-selection');node.textContent=editorAirports[code]?airportDescription(code):'';input.setCustomValidity('');}
function resolveAirport(value){const text=String(value).trim();const code=airportCode(text);if(editorAirports[code])return code;const labelCode=text.match(/\b([A-Za-z]{3})\b/);if(labelCode&&editorAirports[labelCode[1].toUpperCase()])return labelCode[1].toUpperCase();const matches=Object.keys(editorAirports).filter(c=>[editorNames[c],editorAirports[c].city,editorAirports[c].name].some(v=>v&&String(v).toLowerCase()===text.toLowerCase()));return matches.length===1?matches[0]:null;}
function fillRouteHistory(){const select=$('route-history');select.replaceChildren(new Option('选择你记录过的出发和到达机场',''));const routes=new Map();for(const row of state.rows||[]){const a=airportCode(row.from),b=airportCode(row.to);if(!editorAirports[a]||!editorAirports[b])continue;const key=a+'|'+b;routes.set(key,(routes.get(key)||0)+1);}for(const [key,n] of [...routes].sort((a,b)=>b[1]-a[1]).slice(0,80)){const [a,b]=key.split('|');select.add(new Option(`${recordAirportName(a)} ${a} → ${recordAirportName(b)} ${b} · ${n} 条记录`,key));}$('history-wrap').hidden=!routes.size;$('known-airlines').replaceChildren(...[...new Map([...airlineDirectory.map(([icao,code,name])=>[code,`${code} · ${name}`]),...(state.rows||[]).map(r=>{const code=normalizeAirlineCode(r.airline);return [code,code];}).filter(([code])=>code&&validAirlineCode(code))]).entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([code,label])=>new Option(label,code)));}
function openFlightDialog(id=null){if(!editorReady)return;ensureRowIds();const row=id?(state.rows||[]).find(r=>r._id===id):null;if(id&&!row)return;editingId=id;$('flight-form').reset();$('flight-from').setCustomValidity('');$('flight-to').setCustomValidity('');$('flight-dialog-title').textContent=row?'编辑航班记录':'添加一班航班';$('flight-date').value=row?dateValue(row.date)||'':localDate();$('flight-from').value=row?airportCode(row.from):'';$('flight-to').value=row?airportCode(row.to):'';$('flight-airline').value=row?normalizeAirlineCode(row.airline):'';$('flight-number').value=row?String(row.flight||''):'';$('flight-aircraft').value=row?String(row.aircraft||''):'';$('flight-message').textContent='';fillRouteHistory();updateAirportSelection('from');updateAirportSelection('to');$('flight-dialog').showModal();$('flight-date').focus();}
function closeFlightDialog(){if(!editorSaving)$('flight-dialog').close();}
for(const id of ['manual-start','add-record'])$(id).addEventListener('click',()=>openFlightDialog());for(const id of ['flight-close','flight-cancel'])$(id).addEventListener('click',closeFlightDialog);
dismissOnBackdrop($('flight-dialog'),()=>!editorSaving,closeFlightDialog);
for(const which of ['from','to']){$('flight-'+which).addEventListener('input',()=>updateAirportSelection(which));$('flight-'+which).addEventListener('change',()=>{const c=resolveAirport($('flight-'+which).value);if(c)$('flight-'+which).value=c;updateAirportSelection(which);});}
$('swap-airports').addEventListener('click',()=>{const value=$('flight-from').value;$('flight-from').value=$('flight-to').value;$('flight-to').value=value;updateAirportSelection('from');updateAirportSelection('to');});
$('route-history').addEventListener('change',()=>{const pair=$('route-history').value.split('|');if(pair.length!==2)return;$('flight-from').value=pair[0];$('flight-to').value=pair[1];updateAirportSelection('from');updateAirportSelection('to');});
$('flight-form').addEventListener('submit',async e=>{e.preventDefault();if(editorSaving)return;const date=$('flight-date').value;if(!validDate(date)){$('flight-message').textContent='请选择有效的航班日期。';return;}const from=resolveAirport($('flight-from').value),to=resolveAirport($('flight-to').value);for(const [key,value] of [['from',from],['to',to]])if(!value){$('flight-'+key).setCustomValidity('请从机场列表选择，或填写有效的机场三字码。');$('flight-'+key).reportValidity();return;}
 const candidate={date,from,to,airline:normalizeAirlineCode($('flight-airline').value),flight:$('flight-number').value.trim(),aircraft:$('flight-aircraft').value.trim()};
 if((state.rows||[]).some(r=>r._id!==editingId&&recordIdentity(r)===recordIdentity(candidate))){$('flight-message').textContent='相同日期、航司、航班号和方向的记录已存在。请编辑那条记录，或填写不同的航班号。';return;}
 editorSaving=true;$('flight-save').disabled=true;try{if(!state.rows){state.rows=[];state.sheets=[{name:'航班记录',rows:state.rows}];state.fileName='手动航班记录';state.demo=false;$('file-info').textContent='手动航班记录';$('sheet-wrap').hidden=true;}const existing=editingId?state.rows.find(r=>r._id===editingId):null;if(editingId&&!existing)throw Error('这条记录已不存在，请关闭后重试。');if(existing)Object.assign(existing,candidate);else state.rows.push({...candidate,_id:rowId(),_line:'手动'});$('flight-dialog').close();await regenerate();recordFeedback(existing?'已保存修改，地图已更新。':'已添加航班，地图按当前日期设置更新。');}catch(err){$('flight-message').textContent=err.message;}finally{editorSaving=false;$('flight-save').disabled=false;}});
for(const id of ['record-year','record-aircraft'])$(id).addEventListener('change',()=>{recordPage=0;renderRecords();});
$('record-search').addEventListener('input',()=>{recordPage=0;renderRecords();});$('record-filter').addEventListener('change',()=>{recordPage=0;renderRecords();});$('record-prev').addEventListener('click',()=>{recordPage--;renderRecords();});$('record-next').addEventListener('click',()=>{recordPage++;renderRecords();});
$('export-records').addEventListener('click',()=>{try{if(!state.rows?.length)return;const invalidAirlines=(state.sheets.length?state.sheets.flatMap(s=>s.rows):state.rows).map(r=>normalizeAirlineCode(r.airline)).filter(c=>!validAirlineCode(c));if(invalidAirlines.length)throw Error('请先修正航司的两位代码：'+[...new Set(invalidAirlines)].join('、'));const workbook=XLSX.utils.book_new();const sources=state.sheets.length?state.sheets:[{name:'航班记录',rows:state.rows}];const usedNames=new Set();for(const [index,sheet] of sources.entries()){const rows=sheet.rows.map(r=>({'Date':dateValue(r.date)||String(r.date||''),'Airline':normalizeAirlineCode(r.airline),'Flight':String(r.flight||''),'From':airportCode(r.from),'To':airportCode(r.to),'Aircraft Type Name':String(r.aircraft||'')}));const ws=XLSX.utils.json_to_sheet(rows,{header:['Date','Airline','Flight','From','To','Aircraft Type Name']});ws['!cols']=[{wch:13},{wch:12},{wch:12},{wch:10},{wch:10},{wch:26}];let name=String(sheet.name||'航班记录').replace(/[\\/?*\[\]:]/g,'').slice(0,27)||'航班记录';if(usedNames.has(name))name+=' '+(index+1);usedNames.add(name);XLSX.utils.book_append_sheet(workbook,ws,name);}const file=XLSX.write(workbook,{type:'array',bookType:'xlsx'});const url=URL.createObjectURL(new Blob([file],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=`flight-atlas-records-${localDate()}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);recordFeedback('当前记录已导出为 Excel，可在下次导入继续使用。');}catch(err){recordFeedback('导出失败：'+err.message);}});
$('flight-airline').addEventListener('input',()=>{const input=$('flight-airline');input.value=normalizeAirlineCode(input.value);input.setCustomValidity('');});
window.addEventListener('atlas:rows',renderRecords);
Promise.all([assets,fetch('data/airport-zh.json?v=2').then(checkResponse).then(r=>r.json())]).then(([[airports],names])=>{editorAirports=airports;editorNames=names;const fragment=document.createDocumentFragment();for(const [code,a] of Object.entries(airports).sort((a,b)=>a[0].localeCompare(b[0]))){const option=document.createElement('option');option.value=code;option.label=[names[code],a.city,a.name,code].filter(Boolean).join(' · ');fragment.append(option);}$('airport-options').append(fragment);editorReady=true;$('manual-start').disabled=false;$('add-record').disabled=false;$('airport-database-note').replaceChildren(document.createTextNode(`机场查询覆盖 ${Object.keys(airports).length.toLocaleString('zh-CN')} 个机场，支持城市、名称和三字码。来源：`));const link=document.createElement('a');link.href='https://ourairports.com/data/';link.target='_blank';link.rel='noopener noreferrer';link.textContent='OurAirports';$('airport-database-note').append(link);renderRecords();}).catch(err=>{$('airport-database-note').textContent='机场查询加载失败，请刷新页面后重试。';recordFeedback(err.message);});
